"use client";

import { type ReactNode } from "react";
import { cn } from "@/lib/utils";
import { SortHeader } from "./sort-header";
import { SkeletonRows } from "./skeleton-rows";
import { Pagination, type PaginationProps } from "./pagination";
import { Blank } from "./blank";

type SortState = "asc" | "desc" | "none";

/** Per-row visual status, mirroring real-world table needs. */
export type RowStatus = "default" | "selected" | "error" | "pending";

export interface DataTableColumn<T> {
  /** Stable key. */
  key: string;
  /** Header label. */
  header: string;
  /** Cell renderer. */
  cell: (row: T) => ReactNode;
  /** Enables a SortHeader for this column. */
  sortable?: boolean;
  /** Text alignment. */
  align?: "left" | "center" | "right";
  /** Render as numeric (right-aligned, tabular figures). */
  numeric?: boolean;
  /** Optional fixed width / utility classes (e.g. "w-40"). */
  className?: string;
}

interface DataTableProps<T> {
  columns: DataTableColumn<T>[];
  rows: T[];
  /** Unique key per row. */
  rowKey: (row: T) => string;
  loading?: boolean;
  /** Current sort: column key + direction. */
  sort?: { key: string; dir: SortState };
  onSortChange?: (key: string) => void;
  /** Empty-state content when there are no rows and not loading. */
  empty?: { title: string; body: string };
  /** Optional pagination props; renders a footer pager when provided. */
  pagination?: PaginationProps;
  onRowClick?: (row: T) => void;
  /** Optional per-row status → selected / error / pending styling + left bar. */
  rowStatus?: (row: T) => RowStatus;
  /** Zebra-stripe even rows. */
  zebra?: boolean;
  /** Optional header toolbar: title + count/subtitle. */
  title?: string;
  subtitle?: string;
  /** Accessible table caption (visually hidden). */
  caption?: string;
}

const ALIGN: Record<NonNullable<DataTableColumn<unknown>["align"]>, string> = {
  left: "text-left",
  center: "text-center",
  right: "text-right",
};

/**
 * DataTable — a reusable table that composes SortHeader, SkeletonRows,
 * Pagination and an empty state. Column-driven and controlled (bring your
 * own data + sort state), so it works with client or server sorting.
 *
 * Row states (selected / error / pending) and numeric/aligned columns mirror
 * the patterns proven in production table usage (boda-plus-web).
 */
export function DataTable<T>({
  columns,
  rows,
  rowKey,
  loading,
  sort,
  onSortChange,
  empty,
  pagination,
  onRowClick,
  rowStatus,
  zebra,
  title,
  subtitle,
  caption,
}: DataTableProps<T>) {
  const showEmpty = !loading && rows.length === 0;

  return (
    <div className="relative overflow-hidden rounded-xl border border-border bg-surface">
      {/* Top loading bar */}
      {loading && (
        <div className="absolute inset-x-0 top-0 z-10 h-0.5 animate-pulse bg-accent" aria-hidden />
      )}

      {/* Optional toolbar */}
      {(title || subtitle) && (
        <div className="flex min-h-14 flex-wrap items-center gap-3 border-b border-border px-4 py-3">
          <div className="min-w-0 flex-1">
            {title && <h2 className="truncate text-sm font-semibold text-text">{title}</h2>}
            {subtitle && <p className="mt-0.5 truncate text-xs tabular-nums text-text-secondary">{subtitle}</p>}
          </div>
        </div>
      )}

      <div className="overflow-x-auto">
        <table className="w-full border-collapse text-left text-sm">
          {caption && <caption className="sr-only">{caption}</caption>}
          <thead>
            <tr className="border-b border-border">
              {columns.map((col) => {
                const align = col.numeric ? "right" : col.align ?? "left";
                return col.sortable ? (
                  <SortHeader
                    key={col.key}
                    label={col.header}
                    state={sort?.key === col.key ? sort.dir : "none"}
                    onClick={() => onSortChange?.(col.key)}
                  />
                ) : (
                  <th
                    key={col.key}
                    scope="col"
                    className={cn(
                      "px-4 py-2.5 text-xs font-medium uppercase tracking-wider text-text-secondary",
                      ALIGN[align],
                      col.className
                    )}
                  >
                    {col.header}
                  </th>
                );
              })}
            </tr>
          </thead>
          <tbody>
            {loading ? (
              <SkeletonRows n={6} colCount={Math.max(1, columns.length - 1)} />
            ) : (
              rows.map((row, i) => {
                const status = rowStatus?.(row) ?? "default";
                return (
                  <tr
                    key={rowKey(row)}
                    onClick={onRowClick ? () => onRowClick(row) : undefined}
                    aria-selected={status === "selected" || undefined}
                    className={cn(
                      "group relative border-b border-border transition-colors last:border-0",
                      // zebra (only when the row has no special status)
                      zebra && status === "default" && i % 2 === 1 && "bg-bg",
                      status === "default" && onRowClick && "hover:bg-bg-hover",
                      status === "selected" && "bg-accent-light",
                      status === "error" && "bg-error-light",
                      status === "pending" && "opacity-60",
                      onRowClick && "cursor-pointer",
                      // left status bar
                      (status === "selected" || status === "error") &&
                        "before:absolute before:inset-y-0 before:left-0 before:w-0.5",
                      status === "selected" && "before:bg-accent",
                      status === "error" && "before:bg-error"
                    )}
                  >
                    {columns.map((col) => {
                      const align = col.numeric ? "right" : col.align ?? "left";
                      return (
                        <td
                          key={col.key}
                          className={cn(
                            "px-4 py-3 text-text",
                            ALIGN[align],
                            col.numeric && "tabular-nums",
                            col.className
                          )}
                        >
                          {col.cell(row)}
                        </td>
                      );
                    })}
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>

      {showEmpty && (
        <Blank title={empty?.title ?? "No results"} body={empty?.body ?? "There's nothing to show yet."} />
      )}

      {pagination && !showEmpty && <Pagination {...pagination} />}
    </div>
  );
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * Merge class names with clsx semantics + Tailwind conflict resolution.
 * Prefer this in all components.
 */
export function cn(...inputs: ClassValue[]): string {
  return twMerge(clsx(inputs));
}

/**
 * Concatenate class names, filtering out falsy values.
 * @deprecated Prefer {@link cn} — it also resolves Tailwind class conflicts.
 */
export function cx(...args: (string | false | null | undefined)[]): string {
  return args.filter(Boolean).join(" ");
}

/**
 * Focus ring style helper.
 * @deprecated Focus rings are now handled globally via the
 * `:focus-visible` rule in `globals.css` and the `focus-visible:*`
 * utilities. This remains only for backwards compatibility.
 */
export function ring(color: string = "var(--color-accent)") {
  return { outlineColor: color };
}

"use client";

import { ChevronUp, ChevronDown, ChevronsUpDown } from "lucide-react";
import { cn } from "@/lib/utils";

type SortState = "asc" | "desc" | "none";

interface SortHeaderProps {
  label: string;
  state: SortState;
  onClick: () => void;
}

/**
 * SortHeader — sortable table column header.
 * Shows direction indicator when active, subtle icon on hover when inactive.
 * Hover is CSS-driven via `group-hover` (no JS state).
 */
export function SortHeader({ label, state, onClick }: SortHeaderProps) {
  const active = state === "asc" || state === "desc";

  return (
    <th
      scope="col"
      aria-sort={state === "asc" ? "ascending" : state === "desc" ? "descending" : "none"}
      className={cn(
        "px-4 py-2.5 text-left text-xs font-medium uppercase tracking-wider",
        active ? "text-text" : "text-text-secondary"
      )}
    >
      <button
        type="button"
        onClick={onClick}
        className="group inline-flex items-center gap-1.5 rounded uppercase tracking-wider text-inherit focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent"
      >
        {label}
        {state === "asc" ? (
          <ChevronUp size={13} strokeWidth={2.5} aria-hidden />
        ) : state === "desc" ? (
          <ChevronDown size={13} strokeWidth={2.5} aria-hidden />
        ) : (
          <ChevronsUpDown
            size={13}
            aria-hidden
            className="text-text-tertiary opacity-0 transition-opacity group-hover:opacity-100"
          />
        )}
      </button>
    </th>
  );
}

"use client";

interface SkeletonRowsProps {
  n?: number;
  colCount?: number;
}

/**
 * SkeletonRows — loading placeholder rows for tables.
 * Renders n rows with animated pulse skeletons.
 */
export function SkeletonRows({ n = 8, colCount = 3 }: SkeletonRowsProps) {
  return (
    <>
      {Array.from({ length: n }).map((_, i) => (
        <tr key={i} className="border-t border-border">
          <td className="px-4 py-3">
            <span className="block h-4 w-4 rounded-sm bg-bg-secondary" />
          </td>
          <td className="px-4 py-3">
            <span className="flex items-center gap-3">
              <span className="h-8 w-8 shrink-0 animate-pulse rounded-full bg-bg-secondary" />
              <span className="flex-1">
                <span
                  className="block h-3 animate-pulse rounded bg-bg-secondary"
                  style={{ width: `${55 + ((i * 7) % 30)}%` }}
                />
                <span
                  className="mt-1.5 block h-2.5 animate-pulse rounded bg-bg-secondary"
                  style={{ width: `${40 + ((i * 11) % 25)}%` }}
                />
              </span>
            </span>
          </td>
          {Array.from({ length: colCount }).map((_, c) => (
            <td key={c} className="px-4 py-3">
              <span
                className="block h-3 animate-pulse rounded bg-bg-secondary"
                style={{ width: `${45 + ((c * 13 + i * 5) % 35)}%` }}
              />
            </td>
          ))}
          <td className="px-4 py-3" />
        </tr>
      ))}
    </>
  );
}

"use client";

import { ChevronLeft, ChevronRight } from "lucide-react";
import { cn } from "@/lib/utils";

/* ═══════════════════════════════════════════════════════════════
   Pagination — simplified two-zone layout.

   Left  : "126–150 of 1,284  |  Rows [25 ▾]"
   Right : "‹  1  …  5  [6]  7  …  52  ›   Go to [__]"

   Removed: first/last double-chevron buttons (cluttered, rarely used)
            ellipsis-click-to-jump-input (Go-to field covers this)
   ═══════════════════════════════════════════════════════════════ */

export interface PaginationMeta {
  page: number;
  perPage: number;
  totalItems: number;
  totalPages: number;
  from: number;
  to: number;
}

export interface PaginationProps {
  meta?: PaginationMeta;
  page?: number;
  pages?: number;
  perPage?: number;
  total?: number;
  onPageChange: (page: number) => void;
  onPerPageChange: (perPage: number) => void;
  perPageOptions?: number[];
  disabled?: boolean;
  className?: string;
}

function buildPages(page: number, totalPages: number): (number | "…")[] {
  const out: (number | "…")[] = [1];
  if (page > 4) out.push("…");
  for (let p = Math.max(2, page - 1); p <= Math.min(totalPages - 1, page + 1); p++) out.push(p);
  if (page < totalPages - 3) out.push("…");
  if (totalPages > 1) out.push(totalPages);
  return out;
}

export function Pagination({
  meta,
  page: pageProp,
  pages: pagesProp,
  perPage: perPageProp,
  total: totalProp,
  onPageChange,
  onPerPageChange,
  perPageOptions = [10, 25, 50, 100],
  disabled,
  className,
}: PaginationProps) {
  const page       = meta ? meta.page       : (pageProp    ?? 1);
  const totalPages = meta ? meta.totalPages  : (pagesProp   ?? 1);
  const perPage    = meta ? meta.perPage     : (perPageProp ?? 25);
  const total      = meta ? meta.totalItems  : (totalProp   ?? 0);
  const from       = meta ? meta.from : (page - 1) * perPage + 1;
  const to         = meta ? meta.to   : Math.min(page * perPage, total);

  const navBtn = cn(
    "flex h-8 w-8 items-center justify-center rounded-md border border-border text-text-secondary",
    "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent",
    "hover:bg-bg-hover disabled:cursor-not-allowed disabled:opacity-40"
  );

  return (
    <div
      className={cn(
        "flex flex-col gap-3 border-t border-border px-4 py-3 lg:flex-row lg:items-center lg:justify-between",
        disabled && "opacity-50",
        className
      )}
    >
      {/* ── Zone 1 — position in data ──────────────────────── */}
      <div className="flex items-center gap-3 text-sm text-text-secondary">
        <span className="tabular-nums">
          <span className="font-medium text-text">
            {from.toLocaleString()}–{to.toLocaleString()}
          </span>
          {" of "}
          <span className="font-medium text-text">{total.toLocaleString()}</span>
        </span>
        <span className="h-4 w-px shrink-0 bg-border" />
        <label className="flex items-center gap-1.5">
          <span className="hidden sm:inline">Rows</span>
          <select
            value={perPage}
            onChange={(e) => onPerPageChange(Number(e.target.value))}
            aria-label="Rows per page"
            className="h-8 rounded-md border border-border bg-surface px-2 text-sm tabular-nums text-text focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent"
          >
            {perPageOptions.map((n) => <option key={n} value={n}>{n}</option>)}
          </select>
        </label>
      </div>

      {/* ── Zone 2 — navigation ────────────────────────────── */}
      <nav aria-label="Pagination" className="flex items-center justify-between gap-1 lg:justify-end">
        {/* Previous */}
        <button
          type="button"
          onClick={() => page > 1 && onPageChange(page - 1)}
          disabled={page === 1}
          aria-label="Previous page"
          className={navBtn}
        >
          <ChevronLeft size={15} aria-hidden />
        </button>

        {/* Numbered page buttons — md+ */}
        <span className="hidden items-center gap-1 md:flex">
          {buildPages(page, totalPages).map((p, i) =>
            p === "…" ? (
              <span
                key={`e${i}`}
                className="flex h-8 w-8 select-none items-center justify-center text-sm text-text-tertiary"
                aria-hidden
              >
                …
              </span>
            ) : (
              <button
                key={p}
                type="button"
                onClick={() => onPageChange(p as number)}
                aria-current={p === page ? "page" : undefined}
                className={cn(
                  "h-8 min-w-8 rounded-md border px-1.5 text-sm tabular-nums",
                  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent",
                  p === page
                    ? "border-accent bg-accent font-medium text-on-accent"
                    : "border-border text-text-secondary hover:bg-bg-hover"
                )}
              >
                {p}
              </button>
            )
          )}
        </span>

        {/* Mobile — page indicator */}
        <span className="px-2 text-sm tabular-nums text-text-secondary md:hidden">
          <span className="font-medium text-text">{page}</span>
          {" / "}{totalPages}
        </span>

        {/* Next */}
        <button
          type="button"
          onClick={() => page < totalPages && onPageChange(page + 1)}
          disabled={page === totalPages}
          aria-label="Next page"
          className={navBtn}
        >
          <ChevronRight size={15} aria-hidden />
        </button>

        {/* Go to page ───────────────────────────────────────── */}
        <span className="ml-3 hidden items-center gap-1.5 border-l border-border pl-3 text-sm md:flex">
          <label htmlFor="pagination-jump" className="whitespace-nowrap text-xs text-text-tertiary">
            Go to
          </label>
          <input
            id="pagination-jump"
            type="number"
            min={1}
            max={totalPages}
            aria-label={`Go to page (1–${totalPages})`}
            placeholder={String(page)}
            className="h-8 w-14 rounded-md border border-border px-1.5 text-center text-sm tabular-nums text-text focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent"
            onKeyDown={(e) => {
              if (e.key === "Enter") {
                const v = Number(e.currentTarget.value);
                if (v >= 1 && v <= totalPages) { onPageChange(v); e.currentTarget.value = ""; }
              }
              if (e.key === "Escape") { e.currentTarget.value = ""; e.currentTarget.blur(); }
            }}
            onBlur={(e) => {
              const v = Number(e.currentTarget.value);
              if (v >= 1 && v <= totalPages) { onPageChange(v); e.currentTarget.value = ""; }
            }}
          />
        </span>
      </nav>
    </div>
  );
}

"use client";

import type { LucideIcon } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "./button";

type BlankTone = "rose" | "amber" | "neutral";

interface BlankProps {
  icon?: LucideIcon;
  title: string;
  body: string;
  primary?: string;
  secondary?: string;
  mono?: string;
  tone?: BlankTone;
  onPrimary?: () => void;
  onSecondary?: () => void;
}

const TONE_TEXT: Record<BlankTone, string> = {
  rose: "text-error",
  amber: "text-warning",
  neutral: "text-text-tertiary",
};

/**
 * Blank — empty/error state for tables.
 * Use when the table has no rows to show (empty, filtered-empty, error, forbidden).
 */
export function Blank({
  icon: Icon,
  title,
  body,
  primary,
  secondary,
  mono,
  tone = "neutral",
  onPrimary,
  onSecondary,
}: BlankProps) {
  return (
    <div className="flex flex-col items-center px-6 py-16 text-center">
      {Icon && <Icon size={22} className={TONE_TEXT[tone]} aria-hidden />}
      <p className="mt-3 text-base font-medium text-text">{title}</p>
      <p className="mx-auto mt-1 max-w-sm text-sm leading-relaxed text-text-secondary">{body}</p>
      <div className="mt-4 flex flex-wrap items-center justify-center gap-2">
        {primary && (
          <Button onClick={onPrimary}>{primary}</Button>
        )}
        {secondary && (
          <Button variant="secondary" onClick={onSecondary}>{secondary}</Button>
        )}
      </div>
      {mono && <p className="mt-5 font-mono text-[11px] text-text-tertiary">{mono}</p>}
    </div>
  );
}
